var getList = function(key, num, path, arr) {
  let list = JSON.parse(java.fetch("https://api.mangacopy.com/api/v3/comic/"+path+"/group/"+key+"/chapters?limit=100&offset="+num,{method:"get",headers:{"user-agent":"Mozilla/5.0 (Android 9; Mobile; rv:68.0) Gecko/68.0 Firefox/68.0","platform":"1","region":"0","version":"2024.01.08","webp":"1"}}).body().string()).results.list;
  if (!list[0]) return arr;
  arr.push.apply(arr, list);
  return getList(key, num+100, path, arr);
}
var results = JSON.parse(result).results;
var groups = Object.keys(results.groups);
var chaplist = new Array();
groups.reverse().forEach((key,i)=>{
    chaplist.push({
      _id: String.fromCharCode("A".charCodeAt()+i),
      _name: results.groups[key].name
    });
    getList(results.groups[key].path_word, 0, results.comic.path_word, chaplist);
});
chaplist

